using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class MusicGatheringChecks {
 static void Require(bool value,string message){if(!value)throw new Exception(message);}
 [MenuItem("BWVR/Verify music gathering model")]
 public static void VerifyModel(){var dry=new SocialMemory();Require(dry.RememberMusic(false,0,0)&&dry.musicInterest>.5f&&dry.restNeed<.5f,"Dry gathering has no benefit");Require(!dry.RememberMusic(false,0,1)&&dry.musicGatherings==1,"Duplicate audience reward");var wet=new SocialMemory();Require(wet.RememberMusic(false,1,0)&&wet.musicInterest<.5f&&wet.musicDisappointments==1,"Rain has no consequence");var covered=new SocialMemory();Require(covered.RememberMusic(true,1,0)&&covered.musicDisappointments==0,"Cover did not protect comfort");Require(JsonUtility.FromJson<SocialMemory>(JsonUtility.ToJson(covered)).Valid(),"Audience save invalid");covered.musicInterest=float.NaN;Require(!covered.Valid(),"Invalid preference accepted");Require(new SliceState().Valid(),"Legacy save rejected");Debug.Log("BWVR_MUSIC_GATHERING_MODEL_PASS");}
 [MenuItem("BWVR/Verify music audience (Play mode)")]
 public static void VerifyRuntime(){Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var instrument=slice.GetComponentInChildren<SharedRhythm>();var prop=instrument.GetComponent<CreatureAffordance>();var people=slice.GetComponentsInChildren<VillagerSocial>();var jobs=people.Select(p=>p.GetComponent<VillagerExploration>()).ToArray();var nav=god.GetComponent<IslandNavigator>();var ball=slice.GetComponentInChildren<BeachBall>();var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=field.GetValue(slice);var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var tp=prop.transform.position;var tr=prop.transform.rotation;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,hunger=.1f};field.SetValue(slice,test);
  try{god.Interrupt("Audience QA");foreach(var p in people){p.ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.Memory.injury=0;p.Memory.frights=0;p.Memory.trust=.7f;}slice.GetComponentInChildren<VillageFamilies>().ResetWorld();if(!nav.world.Sample(ball.GetComponent<CarryItem>().home,nav.profile,12,out var safe)||!nav.world.Sample(safe+Vector3.right*nav.world.Scale*10,nav.world.villager,5,out var hostAt))throw new Exception("No music stage");god.transform.position=nav.world.ProjectFoot(safe,nav.profile);nav.ResetRoute();var host=people[0];host.transform.position=nav.world.ProjectFoot(hostAt,nav.world.villager);host.GetComponent<IslandNavigator>().ResetRoute();test.Hybrid.motivation=new CreatureMotivation();foreach(var target in god.Targets)if(target.affordance!=null)target.affordance.cooldown=1000;prop.cooldown=0;prop.Item.held=false;prop.transform.position=host.transform.position+Vector3.up*nav.world.Scale*.7f;host.Memory.nextInvitationAt=0;Require(host.TryShare(prop),"Host refused native invitation");for(int i=0;i<1600&&!host.Ready&&host.Active;i++){test.Hybrid.time+=.05f;host.Tick(.05f,false);}Require(host.Ready,"Host failed to present chime");
   // Keep spectators close to a real performance, using the normal visibility gates.
   for(int i=1;i<people.Length;i++){float a=(i*31+40)*Mathf.Deg2Rad;var wanted=host.transform.position+new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*nav.world.Scale*(i<5?12:100);if(nav.world.Sample(wanted,nav.world.villager,3,out var at))people[i].transform.position=nav.world.ProjectFoot(at,nav.world.villager);people[i].transform.LookAt(new Vector3(host.transform.position.x,people[i].transform.position.y,host.transform.position.z));people[i].Memory.nextMusicAt=0;people[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();for(int i=0;i<1200&&!instrument.Active;i++){test.Hybrid.time+=.05f;god.Tick(.05f);host.Tick(.05f,false);}Require(instrument.Active,"Creature declined isolated feasible chime");Require(instrument.AudienceCount>0&&instrument.AudienceCount<=3,"No bounded native audience");var listeners=jobs.Where(j=>j.MusicAudience).ToArray();var picked=listeners[0];picked.GetComponent<CarryItem>().held=true;picked.Tick(.1f,false);picked.GetComponent<CarryItem>().held=false;Require(!picked.MusicAudience,"Pickup retained spectator ownership");picked.TryWatchMusic(instrument);listeners=jobs.Where(j=>j.MusicAudience).ToArray();Require(listeners.Length>0,"No listeners after pickup");float interest=listeners[0].GetComponent<VillagerSocial>().Memory.musicInterest;test.paused=true;int beats=instrument.Beats;foreach(var j in listeners)j.Tick(1,true);Require(instrument.Tick(1)==0&&instrument.Beats==beats,"Paused music progressed");test.paused=false;
   for(int i=0;i<300&&!instrument.Completed;i++){test.Hybrid.time+=.05f;foreach(var j in jobs.Where(j=>j.MusicAudience))j.Tick(.05f,false);god.Tick(.05f);host.Tick(.05f,false);}Require(instrument.Completed&&instrument.Beats==8,"Native reciprocal performance failed");Require(people.Sum(p=>p.Memory.musicGatherings)>0&&instrument.AudienceCount==0,"No observed outcome or leaked reservations");foreach(var j in listeners){int count=j.GetComponent<VillagerSocial>().Memory.musicGatherings;j.WitnessMusic(instrument);Require(j.GetComponent<VillagerSocial>().Memory.musicGatherings==count,"Outcome credited twice");}Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Gathering season invalid");Debug.Log("BWVR_MUSIC_GATHERING_RUNTIME_PASS: native invitation, autonomous utility acceptance, bounded visible audience, pickup cleanup, pause, eight beats, completion-only memory and persistence");
  }finally{instrument.Cancel();foreach(var p in people){p.GetComponent<CarryItem>().held=false;p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();}god.Interrupt("Audience QA complete");field.SetValue(slice,original);for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}god.transform.SetPositionAndRotation(gp,gr);god.NewSeason();prop.Item.held=false;prop.host=null;prop.transform.SetPositionAndRotation(tp,tr);prop.GetComponent<Collider>().enabled=true;slice.GetComponentInChildren<VillageFamilies>().ResetWorld();}
 }
}
}
